test("揃えを書いていない column の親の下でフローの Text を包むと、Box の幅が fill になる", () => {
  const grouped = group(
    setupPanelDocument({ layout: "column" }, [{ name: "title", type: "Text" }]),
    ["title"],
  );

  expect(propsOf(grouped, "box")).toEqual({ widthMode: "fill" });
});

test("layout: row の親の下でフローの Text を包むと、Box の高さが fill になる", () => {
  const grouped = group(
    setupPanelDocument({ layout: "row" }, [{ name: "title", type: "Text" }]),
    ["title"],
  );

  expect(propsOf(grouped, "box")).toEqual({ heightMode: "fill" });
});

test("何も書いていない artboard の直下で Text を包むと、Box の幅が fill になる", () => {
  const document = setupArtboardDocument({
    children: [{ name: "title", type: "Text" }],
  });

  expect(propsOf(group(document, ["title"]), "box")).toEqual({
    widthMode: "fill",
  });
});

test("layout: row と書いた artboard の直下で Text を包むと、Box の高さが fill になる", () => {
  const document = setupArtboardDocument({
    artboardProps: { layout: "row" },
    children: [{ name: "title", type: "Text" }],
  });

  expect(propsOf(group(document, ["title"]), "box")).toEqual({
    heightMode: "fill",
  });
});

test("揃えが center の column の親の下で Text を包んだ Box は、大きさの prop を持たない", () => {
  const grouped = group(
    setupPanelDocument({ align: "center" }, [{ name: "title", type: "Text" }]),
    ["title"],
  );

  expect(propsOf(grouped, "box")).toEqual({});
});

test("layout: free の親の下で Text を包んだ Box は、大きさの prop を持たない", () => {
  const grouped = group(
    setupPanelDocument({ layout: "free" }, [{ name: "title", type: "Text" }]),
    ["title"],
  );

  expect(propsOf(grouped, "box")).toEqual({});
});

test("揃えが stretch の親の下で絶対配置の Text を包むと、Box は配置だけを持ち fill を持たない", () => {
  const grouped = group(
    setupPanelDocument({}, [
      {
        name: "title",
        type: "Text",
        props: { placement: "absolute", x: 24, y: 48 },
      },
    ]),
    ["title"],
  );

  expect(propsOf(grouped, "box")).toEqual({
    placement: "absolute",
    x: 24,
    y: 48,
  });
});

test("Text を包んでも Text の props は変わらない", () => {
  const grouped = group(
    setupPanelDocument({}, [
      { name: "title", type: "Text", props: { content: "見出し" } },
    ]),
    ["title"],
  );

  expect(propsOf(grouped, "title")).toEqual({ content: "見出し" });
});

test("揃えが stretch の親の下で Ellipse を包んだ Box は、大きさの prop を持たない", () => {
  const grouped = group(
    setupPanelDocument({}, [{ name: "dot", type: "Ellipse" }]),
    ["dot"],
  );

  expect(propsOf(grouped, "box")).toEqual({});
});

test("揃えが stretch の親の下で部品インスタンスを包んだ Box は、大きさの prop を持たない", () => {
  const document = setupArtboardDocument({
    components: { Caption: { type: "Text" } },
    children: [{ name: "caption", ref: "Caption" }],
  });

  expect(propsOf(group(document, ["caption"]), "box")).toEqual({});
});

test("column の親の下で Text と Box をまとめて包むと、Box の幅が fill になる", () => {
  const grouped = group(
    setupPanelDocument({}, [
      { name: "title", type: "Text" },
      { name: "card", type: "Box" },
    ]),
    ["title", "card"],
  );

  expect(propsOf(grouped, "box")).toEqual({ widthMode: "fill" });
});

test("row の親の下で Text と Box をまとめて包むと、Box は row で並べ、高さが fill になる", () => {
  const grouped = group(
    setupPanelDocument({ layout: "row" }, [
      { name: "title", type: "Text" },
      { name: "card", type: "Box" },
    ]),
    ["title", "card"],
  );

  expect(propsOf(grouped, "box")).toEqual({
    layout: "row",
    heightMode: "fill",
  });
});

test("揃えが center の親の下で Text と Box をまとめて包むと、Box は親の揃えだけを持ち fill を持たない", () => {
  const grouped = group(
    setupPanelDocument({ align: "center" }, [
      { name: "title", type: "Text" },
      { name: "card", type: "Box" },
    ]),
    ["title", "card"],
  );

  expect(propsOf(grouped, "box")).toEqual({ align: "center" });
});

test("column の親の下で Box、Text の順にまとめて包んでも、Box の幅が fill になる", () => {
  const grouped = group(
    setupPanelDocument({}, [
      { name: "card", type: "Box" },
      { name: "title", type: "Text" },
    ]),
    ["card", "title"],
  );

  expect(propsOf(grouped, "box")).toEqual({ widthMode: "fill" });
});

test("揃えが stretch の親の下の Text を包んでから外すと、元のドキュメントに戻る", () => {
  const document = setupPanelDocument({}, [
    { name: "title", type: "Text", props: { content: "見出し" } },
  ]);

  const ungrouped = Result.unwrap(
    DesignDocument.ungroupBox(group(document, ["title"]), "box"),
  );

  expect(ungrouped.document).toEqual(document);
});

test("何も書いていない親は、子を幅の軸へ引き伸ばす", () => {
  expect(BoxAlign.stretchedAxis({})).toEqual(Option.some("width"));
});

test("揃えを stretch、layout を column と書いた親は、子を幅の軸へ引き伸ばす", () => {
  expect(
    BoxAlign.stretchedAxis({ align: "stretch", layout: "column" }),
  ).toEqual(Option.some("width"));
});

test("layout: row の親は、子を高さの軸へ引き伸ばす", () => {
  expect(BoxAlign.stretchedAxis({ layout: "row" })).toEqual(
    Option.some("height"),
  );
});

test("揃えが start の親は、子を引き伸ばさない", () => {
  expect(BoxAlign.stretchedAxis({ align: "start" })).toEqual(Option.none);
});

test("揃えが center の親は、子を引き伸ばさない", () => {
  expect(BoxAlign.stretchedAxis({ align: "center" })).toEqual(Option.none);
});

test("揃えが end の親は、子を引き伸ばさない", () => {
  expect(BoxAlign.stretchedAxis({ align: "end" })).toEqual(Option.none);
});

test("layout: free の親は、揃えが stretch でも子を引き伸ばさない", () => {
  expect(BoxAlign.stretchedAxis({ layout: "free" })).toEqual(Option.none);
});

test("引き伸ばされている軸のモードを持たない Text を含む並びは、その軸の幅を fill にする編集になる", () => {
  expect(
    Size.collectAlignStretchFillModePropEdits(
      [PrimitiveTypes.Box, PrimitiveTypes.Text],
      "width",
    ),
  ).toEqual([PropEdit.set(["widthMode"], "fill")]);
});

test("引き伸ばされている軸が高さなら、高さのモードを fill にする編集になる", () => {
  expect(
    Size.collectAlignStretchFillModePropEdits([PrimitiveTypes.Text], "height"),
  ).toEqual([PropEdit.set(["heightMode"], "fill")]);
});

test("全員がその軸のモードを持つ型なら、引き伸ばしを写す編集は空", () => {
  expect(
    Size.collectAlignStretchFillModePropEdits(
      [PrimitiveTypes.Box, PrimitiveTypes.Ellipse],
      "width",
    ),
  ).toEqual([]);
});

test("空の並びなら、引き伸ばしを写す編集は空", () => {
  expect(Size.collectAlignStretchFillModePropEdits([], "width")).toEqual([]);
});

test("フローで fill を持たない Box を包んだ Box は props を持たない", () => {
  const document = DesignDocument.create({
    artboards: [
      {
        name: "screen",
        width: 375,
        height: 812,
        children: [{ name: "title", type: "Box" }],
      },
    ],
  });

  const grouped = Result.unwrap(
    DesignDocument.groupIntoBox(document, ["title"], "box"),
  );
  const box = Option.unwrap(DesignDocument.findNode(grouped, "box"));

  expect(Node.isPrimitive(box) && box.props).toBeUndefined();
});

test("親に何も書かれていなければ、長さのモードを持つフローの兄弟を包んだ Box は props を持たない", () => {
  const grouped = groupPair(setupPanelDocument({}, FlowPair));
  const box = Option.unwrap(DesignDocument.findNode(grouped, "box"));

  expect("props" in box).toBe(false);
});

collectAlignStretchFillModePropEdits(
  types: readonly PrimitiveType[],
  axis: Axis,
): readonly PropEdit[] {
  const hasTypeLackingModeProp = types.some(
    (type) =>
      !Option.isSome(
        PrimitiveSchema.propDefinition(type, Size.modeProp(axis)),
      ),
  );

  return hasTypeLackingModeProp ? [fillModePropEdit(axis)] : [];
},

function collectParentAlignStretchFillModePropEdits(
  members: readonly Node[],
  parentProps: Props,
): readonly PropEdit[] {
  const types = members.flatMap((member) => {
    const isSchemaPrimitive =
      Node.isPrimitive(member) && PrimitiveSchema.isPrimitiveType(member.type);
    return isSchemaPrimitive ? [member.type] : [];
  });

  return Option.unwrapOr(
    Option.map(BoxAlign.stretchedAxis(parentProps), (axis) =>
      Size.collectAlignStretchFillModePropEdits(types, axis),
    ),
    [],
  );
}

/**
 * 親の props から、子を交差軸いっぱいに引き伸ばす軸を返す（docs/03「Box」の `align`。
 * `layout` が `free` 以外のときだけ効く）。
 *
 * @param props 親の props（デフォルト解決済みでなくてよい）
 * @returns 揃えが stretch で子を並べるならその交差軸。揃えが start / center / end か、
 *   `layout: free` なら `none`
 */
stretchedAxis(props: Props): Option<Axis> {
  if (BoxAlign.fromProps(props) !== BoxAligns.Stretch) {
    return Option.none;
  }
  return Option.map(
    Layout.direction(Layout.fromProps(props)),
    CssDirection.crossAxis,
  );
},
